{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "type": "object",
  "properties": {
    "$schema": {
      "description": "JSON Schema URI for editor completion.",
      "type": "string"
    },
    "tabTitle": {
      "type": "object",
      "properties": {
        "enabled": {
          "description": "Enable dynamic Zellij tab title updates.",
          "type": "boolean",
          "default": true
        },
        "emojiIdle": {
          "description": "Prefix used when OpenCode is idle.",
          "type": "string",
          "default": "🟢"
        },
        "emojiRunning": {
          "description": "Prefix used while OpenCode is running work.",
          "type": "string",
          "default": "⚡"
        },
        "emojiNeedsInput": {
          "description": "Prefix used when OpenCode is waiting for human input.",
          "type": "string",
          "default": "💬"
        },
        "debounceMs": {
          "description": "Debounce time for tab title updates in milliseconds.",
          "type": "number",
          "minimum": 0,
          "default": 300
        }
      },
      "additionalProperties": false
    },
    "pty": {
      "type": "object",
      "properties": {
        "enabled": {
          "description": "Enable Zellij-backed PTY tools.",
          "type": "boolean",
          "default": true
        },
        "cleanupExitedPaneOnRead": {
          "description": "Remove exited PTY panes after they are read.",
          "type": "boolean",
          "default": true
        },
        "sudoPane": {
          "description": "Controls whether the sudo pane tool is available, denied, or hidden.",
          "type": "string",
          "enum": [
            "allow",
            "deny",
            "hide"
          ],
          "default": "allow"
        },
        "sudoPaneMode": {
          "description": "How the sudo request pane is presented to the user. `floating` (default) opens a large, pinned floating pane without stealing focus; `fullscreen` opens a non-floating pane that Zellij focuses automatically.",
          "type": "string",
          "enum": [
            "floating",
            "fullscreen"
          ]
        },
        "sudoPaneFloatingSize": {
          "description": "Size of the floating sudo pane. `width`/`height` accept a percent string (e.g. `80%`) or a bare integer in cells. `pinned` keeps the pane on top of other floating panes.",
          "type": "object",
          "properties": {
            "width": {
              "default": "80%",
              "type": "string"
            },
            "height": {
              "default": "60%",
              "type": "string"
            },
            "pinned": {
              "default": true,
              "type": "boolean"
            }
          },
          "required": [
            "width",
            "height",
            "pinned"
          ],
          "additionalProperties": false
        }
      },
      "additionalProperties": false
    }
  },
  "additionalProperties": false,
  "$id": "https://raw.githubusercontent.com/maou-shonen/opencode-zellij/main/opencode-zellij.schema.json",
  "title": "opencode-zellij config"
}

{
  "name": "opencode-zellij",
