  },
  "exports": {
    ".": {
      "types": "./dist/index.d.mts",
      "default": "./dist/index.mjs"
    }
  },
  "main": "./dist/index.mjs",
  "types": "./dist/index.d.mts",
  "files": [
    "dist"
  ],
  "dependencies": {
    "@loglayer/transport-log-file-rotation": "^3.2.0",
    "@opencode-ai/plugin": "latest",
    "confbox": "^0.2.4",
    "loglayer": "^9.3.0",
    "serialize-error": "^13.0.1",
