  },
  "devDependencies": {
    "@antfu/eslint-config": "^8.2.0",
    "@types/bun": "latest",
    "@types/node": "latest",
    "eslint": "^10.3.0",
    "eslint-plugin-markdown-links": "^0.9.0",
    "pkg-pr-new": "^0.0.71",
    "tsdown": "latest",
    "typescript": "latest"
  }
}

